const secret = $json.headers?.['x-ekvaar-secret'];
if (!secret || secret !== $env.N8N_EKVAAR_WEBHOOK_SECRET) throw new Error('Unauthorized Ekvaar request');
const body = $json.body || {};
if (!body.message || !body.system) throw new Error('Missing Krishna prompt');
return [{ json: body }];

const raw = String($json.text ?? $json.output ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
let result;
try { result = start >= 0 && end > start ? JSON.parse(raw.slice(start, end + 1)) : { spoken: raw }; } catch { result = { spoken: raw }; }
if (!result.spoken) throw new Error('Model returned no spoken response');
if (!result.action || typeof result.action.type !== 'string') result.action = { type: 'none' };
return [{ json: result }];
